def adjust_tone(content: str) -> Tuple[str, int]:
    """调整文章语气，返回调整后的内容和替换次数"""
    original_content = content
    total_replacements = 0
    
    for pattern, replacement, desc in REPLACEMENTS:
        matches = len(re.findall(pattern, content))
        if matches > 0:
            content = re.sub(pattern, replacement, content)
            total_replacements += matches
    
    return content, total_replacements

def process_file(file_path: Path) -> bool:
    """处理单个文件"""
    try:
        content = file_path.read_text(encoding='utf-8')
        new_content, count = adjust_tone(content)
        
        if count > 0:
            file_path.write_text(new_content, encoding='utf-8')
            print(f"✓ {file_path.name}: {count} replacements")
            return True
        return False
    except Exception as e:
        print(f"✗ {file_path.name}: {e}")
        return False

def main():
    """主函数"""
    posts_dir = Path("_posts")
    if not posts_dir.exists():
        print(f"Error: {posts_dir} not found")
        return
    
    md_files = list(posts_dir.glob("*.md"))
    print(f"Found {len(md_files)} markdown files")
    print("Processing...")
    
    processed = 0
    for md_file in sorted(md_files):
        if process_file(md_file):
            processed += 1
    
    print(f"\n✓ Processed {processed} files")

if __name__ == "__main__":
    main()
